CREATE POLICY op_moph_creator_insert ON public.op_maintenance_photos FOR INSERT TO authenticated WITH CHECK (uploaded_by = auth.uid() AND EXISTS (SELECT 1 FROM public.op_maintenance_orders mo WHERE mo.id = maintenance_order_id AND mo.created_by = auth.uid() AND public.is_member_of_org(mo.organization_id)));
CREATE POLICY op_moph_technician_insert ON public.op_maintenance_photos FOR INSERT TO authenticated WITH CHECK (uploaded_by = auth.uid() AND EXISTS (SELECT 1 FROM public.op_maintenance_orders mo JOIN public.op_maint_technicians t ON t.id = mo.assigned_technician_id AND t.organization_id = mo.organization_id WHERE mo.id = maintenance_order_id AND t.user_id = auth.uid()));